import yaml
with open('/home/ubuntu/.agent-ml-research-be-idea-gen-0515-2/projects/importance_margin_vla_compress/registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})
# Check which L2norm/Random s45 are NOT yet running/done
for mode in ['l2norm', 'random']:
    for k in ['k05', 'k07', 'k075', 'k085', 'k09', 'k095']:
        pattern = f'pi05_{mode}_{k}_long_seed45'
        matches = [(e, exps[e].get('status'), exps[e].get('conclusion')) for e in exps if pattern in e]
        if matches:
            for eid, st, conc in matches:
                print(f'{eid}: {st}/{conc}')
        else:
            print(f'MISSING: {mode} {k} seed45')
